import { describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { FACT_SPECS } from "../scripts/facts";
import { renderResults } from "../scripts/readme-facts";

const START = "<!-- facts:start -->";
const END = "<!-- facts:end -->";
const readme = `# Roster\n\n**Status:**\n${START}\nstale hand-typed text\n${END}\n\n## Run it`;

// The shape scripts/facts.ts writes: "KEY = value  (source: …, generated …)".
const factsDoc = [
  "<!-- GENERATED by scripts/facts.ts from reports/. Do not edit by hand. -->",
  "# Facts",
  "",
  "SELF_SESSIONS = 61 sessions  (source: reports/rajkaria__roster/review.json#$.setups[*].sessions, generated T)",
  "SELF_SPEND_USD = ≥28.60 USD, rounded to 2 decimals  (source: reports/rajkaria__roster/review.json#$.setups[*].spend_usd, generated T)",
  "SELF_LABEL = no_suspect  (source: reports/rajkaria__roster/review.json#$.label, generated T)",
  "FORWARD_P = PENDING  (source: reports/self/forward.json#$.mcnemar.p, generated T)",
  "",
].join("\n");

describe("renderResults", () => {
  test("replaces only the block between the markers, one bullet per key", () => {
    const out = renderResults(readme, factsDoc, ["SELF_SESSIONS", "SELF_LABEL"]);
    expect(out).toBe(
      `# Roster\n\n**Status:**\n${START}\n- SELF_SESSIONS: 61 sessions\n- SELF_LABEL: no_suspect\n${END}\n\n## Run it`,
    );
    expect(out).not.toContain("stale hand-typed text");
  });

  test("keeps the key order it was given and keeps units and rounding as FACTS spells them", () => {
    const out = renderResults(readme, factsDoc, ["SELF_SPEND_USD", "SELF_SESSIONS"]);
    expect(out.split("\n").slice(4, 6)).toEqual([
      "- SELF_SPEND_USD: ≥28.60 USD, rounded to 2 decimals",
      "- SELF_SESSIONS: 61 sessions",
    ]);
  });

  test("a missing key and a PENDING value both render pending", () => {
    const out = renderResults(readme, factsDoc, ["FORWARD_P", "NOT_A_FACT", "SELF_LABEL"]);
    expect(out).toContain("- FORWARD_P: pending\n- NOT_A_FACT: pending\n- SELF_LABEL: no_suspect\n");
  });

  test("markers absent or out of order leave the README alone", () => {
    expect(renderResults("# No markers\n\ncontent", factsDoc, ["SELF_SESSIONS"])).toBe("# No markers\n\ncontent");
    expect(renderResults(`${START}\nonly the opening marker`, factsDoc, ["SELF_SESSIONS"])).toBe(`${START}\nonly the opening marker`);
    expect(renderResults(`${END}\nbackwards\n${START}`, factsDoc, ["SELF_SESSIONS"])).toBe(`${END}\nbackwards\n${START}`);
  });

  test("running twice changes nothing further", () => {
    const keys = ["SELF_SESSIONS", "SELF_LABEL", "FORWARD_P", "NOT_A_FACT"];
    const once = renderResults(readme, factsDoc, keys);
    expect(renderResults(once, factsDoc, keys)).toBe(once);
    expect(renderResults(renderResults(once, factsDoc, keys), factsDoc, keys)).toBe(once);
  });

  test("a key is matched as a whole line prefix, not as a substring", () => {
    const facts = ["SELF_P = 1.000  (source: review)", "SELF_P_VALUE = 9  (source: review)"].join("\n");
    expect(renderResults(`${START}\n${END}`, facts, ["SELF_P"])).toBe(`${START}\n- SELF_P: 1.000\n${END}`);
  });

  test("a value is never taken from a line that only looks like a fact", () => {
    const facts = ["note: SELF_P = 1.000", "SELF_P = 1.000  (source: review)"].join("\n");
    expect(renderResults(`${START}\n${END}`, facts, ["SELF_P"])).toBe(`${START}\n- SELF_P: 1.000\n${END}`);
  });

  test("an empty key list empties the block instead of leaving stale text", () => {
    expect(renderResults(`${START}\nold\n${END}`, factsDoc, [])).toBe(`${START}\n\n${END}`);
  });

  test("the generated docs/FACTS.md feeds the keys the README cites", () => {
    const facts = readFileSync(join(import.meta.dir, "..", "docs", "FACTS.md"), "utf8");
    const out = renderResults(readme, facts, ["SELF_SESSIONS", "SELF_LABEL"]);
    expect(out).toContain("- SELF_SESSIONS: ");
    expect(out).not.toContain("- SELF_SESSIONS: pending");
    // Every spec key with a real value in FACTS renders as a value, not as pending, or is PENDING there too.
    for (const key of FACT_SPECS.map((s) => s.key)) {
      const bullet = renderResults(`${START}\n${END}`, facts, [key]).split("\n")[1];
      const inFacts = new RegExp(`^${key} = `, "m").test(facts);
      expect(bullet === `- ${key}: pending`).toBe(!inFacts || new RegExp(`^${key} = PENDING `, "m").test(facts));
    }
  });
});

